window.ox.install(({action})=>{async function entry(){const end=Date.now()+15000;while(Date.now()<end){const e=document.getElementById('temail'),b=document.getElementById('btn-submit');if(e&&b){const r=e.getBoundingClientRect();if(r.width>0&&r.height>0&&getComputedStyle(e).visibility==='visible')return true;}await new Promise(r=>setTimeout(r,200));}return false;}action('login',{async invoke(){if(!await entry())throw Error('USPS enrollment entry unavailable; inspect live state.');return null;}});async function dashboard(){const end=Date.now()+20000;while(Date.now()<end){if(location.hostname==='verified.usps.com'&&location.pathname==='/am/XUI/'&&document.querySelector('input[type="password"]')&&document.querySelector('#loginButton_0'))return null;if(document.querySelector('#temail'))return null;const root=document.querySelector('#root'),name=document.querySelector('#anchor-login')?.textContent.trim(),address=document.querySelector('#account-address-single')?.textContent.trim();if(root&&name?.startsWith('Hi,')&&address&&root.innerText.includes('Welcome to Informed Delivery'))return {id:name+'|'+address,label:name.replace(/^Hi,\s*/,''),url:'https://informeddelivery.usps.com/portal/dashboard?mode=id-login',text:root.innerText};await new Promise(r=>setTimeout(r,250));}throw Error('Dashboard identity or enrollment readiness unavailable');}action('listSessions',{async invoke(){const d=await dashboard();return d?[{id:d.id,label:d.label,url:d.url}]:[];}});action('getEnrollmentStatus',{async invoke(args,{session}){const d=await dashboard();if(!d)throw Error('Not signed in');if(session?.id&&d.id!==session.id)throw Error('Account mismatch');const a=d.text.match(/(\d+)\s*Mailpieces/),b=d.text.match(/(\d+)\s*Packages/);return {dashboardAvailable:true,mailpieces:a?Number(a[1]):null,packages:b?Number(b[1]):null,url:d.url};}});});